    function getVaultCount() external view returns (uint256) {
        return vaults.length;
    }

    function getAllVaults() external view returns (address[] memory) {
        return vaults;
    }

    function getVaultInfo(address user) external view returns (
        address vault,
        uint256 usdtBalance,
        uint256 bnbBalance,
        int256 totalPnl,
        uint256 totalTrades,
        uint256 totalFees,
        bool paused
    ) {
        vault = userVaults[user];
        if (vault == address(0)) return (address(0), 0, 0, 0, 0, 0, false);

        AgentVaultV2 v = AgentVaultV2(payable(vault));
        usdtBalance = v.getUSDTBalance();
        bnbBalance = v.getBNBBalance();
        totalPnl = v.totalPnl();
        totalTrades = v.getTradeCount();
        totalFees = v.totalFeesCollected();
        paused = v.isPaused();
    }
}

contracts/AgentVaultV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AgentVault V3 — 用户智能合约钱包（完全修复版）
 * 
 * 修复清单：
 *   1. Ownable(_userAddress) — 部署时 ownership 归用户，用户可自由提现和设置
 *   2. executeSwap path 用 address[] 数组编码（不用 encodePacked）
 *   3. 默认限额 1e18（BSC USDT 18位小数）
 *   4. swapBNBForTokens path 同样用 address[]
 *   5. recordPnl 限额验证改用合理范围
 * 
 * 安全机制：
 *   - 只有 owner（用户）可以存取资金、设置限额、撤销 trader
 *   - trader（平台执行器）只能 swap（不能提现）
 *   - 白名单 DEX + 单笔限额 + 日限额
 *   - 紧急暂停功能
 */

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract AgentVaultV2 is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ 常量 ============
    address constant USDT = 0x55d398326f99059fF775485246999027B3197955;
    address constant WBNB = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
    address constant PANCAKE_V2_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address constant PANCAKE_V3_ROUTER = 0x13f4eA83D0bD40E75c336312Cf81599DFE530382;

    // ============ 状态变量 ============

    /// @notice 平台执行器地址（可以执行交易）
    address public trader;

    /// @notice 平台收入钱包（收取服务费）
    address public platformFeeWallet;

    /// @notice 用户钱包地址
    address public userAddress;

    /// @notice 平台服务费比例（基点，2000 = 20%）
    uint256 public platformFeeBps;

    /// @notice 已授权的 DEX 合约白名单
    mapping(address => bool) public approvedDexes;

    /// @notice 单笔交易最大金额（18位小数）
    uint256 public maxSingleTradeAmount;

    /// @notice 日交易累计金额
    uint256 public dailyTradeVolume;

    /// @notice 日交易重置时间戳
    uint256 public dailyResetTimestamp;

    /// @notice 日交易限额（18位小数）
    uint256 public dailyTradeLimit;

    /// @notice 总交易次数
    uint256 public totalTrades;

    /// @notice 总盈亏（正=盈利，负=亏损）
    int256 public totalPnl;

    /// @notice 已收取的平台费
    uint256 public totalFeesCollected;

    /// @notice Vault 部署时间
    uint256 public createdAt;

    // ============ 结构体 ============

    struct TradeRecord {
        uint256 id;
        address dex;
        address tokenIn;
        address tokenOut;
        uint256 inputAmount;
        uint256 outputAmount;
        int256 pnl;
        uint256 timestamp;
        bool success;
    }

    TradeRecord[] public trades;

    // ============ 事件 ============

    event TraderUpdated(address indexed oldTrader, address indexed newTrader);
    event DexApproved(address indexed dex, bool approved);
    event TradeExecuted(uint256 indexed tradeId, address indexed dex, uint256 inputAmount, uint256 outputAmount, uint256 timestamp);
    event PlatformFeeCollected(uint256 amount, uint256 timestamp);
    event UserDeposit(address indexed token, uint256 amount, uint256 timestamp);
    event UserWithdraw(address indexed token, uint256 amount, uint256 timestamp);
    event EmergencyStop(uint256 timestamp);
    event TradeLimitsUpdated(uint256 maxSingle, uint256 dailyLimit);

    // ============ 修饰器 ============

    modifier onlyTrader() {
        require(msg.sender == trader, "Not trader");
        _;
    }

    // ============ 构造函数 ============

    constructor(
        address _userAddress,
        address _trader,
        address _platformFeeWallet,
        uint256 _platformFeeBps
    ) Ownable(_userAddress) {
        require(_userAddress != address(0), "Invalid user");
        require(_trader != address(0), "Invalid trader");
        require(_platformFeeWallet != address(0), "Invalid fee wallet");
        require(_platformFeeBps <= 3000, "Fee too high");

        userAddress = _userAddress;
        trader = _trader;
        platformFeeWallet = _platformFeeWallet;
        platformFeeBps = _platformFeeBps;
        createdAt = block.timestamp;

        // 自动批准 PancakeSwap Router
        approvedDexes[PANCAKE_V2_ROUTER] = true;
        approvedDexes[PANCAKE_V3_ROUTER] = true;

        // 默认交易限额（18位小数）
        maxSingleTradeAmount = 50000 * 1e18;
        dailyTradeLimit = 200000 * 1e18;
        dailyResetTimestamp = block.timestamp;
    }

    // ============ 资金管理（只有 owner）===========

    function depositUSDT(uint256 amount) external whenNotPaused {
        require(amount > 0, "Amount must be > 0");
        IERC20(USDT).safeTransferFrom(msg.sender, address(this), amount);
        emit UserDeposit(USDT, amount, block.timestamp);
    }

    function depositBNB() external payable nonReentrant whenNotPaused {
        require(msg.value > 0, "Amount must be > 0");
        emit UserDeposit(address(0), msg.value, block.timestamp);
    }

    function withdrawUSDT(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Amount must be > 0");
        IERC20 usdt = IERC20(USDT);
        require(usdt.balanceOf(address(this)) >= amount, "Insufficient USDT");
        usdt.safeTransfer(owner(), amount);
        emit UserWithdraw(USDT, amount, block.timestamp);
    }

    function withdrawBNB(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(address(this).balance >= amount, "Insufficient BNB");
        (bool success, ) = payable(owner()).call{value: amount}("");
        require(success, "BNB transfer failed");
        emit UserWithdraw(address(0), amount, block.timestamp);
    }

    function withdrawAllUSDT() external onlyOwner nonReentrant {
        IERC20 usdt = IERC20(USDT);
        uint256 balance = usdt.balanceOf(address(this));
        require(balance > 0, "No USDT to withdraw");
        usdt.safeTransfer(owner(), balance);
        emit UserWithdraw(USDT, balance, block.timestamp);
    }

    function withdrawAllBNB() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No BNB to withdraw");
        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "BNB transfer failed");
        emit UserWithdraw(address(0), balance, block.timestamp);
    }

    // ============ 交易执行（只有 trader）===========

    /**
     * @notice 执行 Token→Token swap
     * @param dex DEX Router 地址（必须在白名单）
     * @param tokenIn 输入 token
     * @param tokenOut 输出 token
     * @param amountIn 输入金额
     * @param minAmountOut 最小输出（滑点保护）
     */
    function executeSwap(
        address dex,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut
    ) external onlyTrader whenNotPaused returns (uint256 outputAmount) {
        require(approvedDexes[dex], "DEX not approved");
        require(amountIn > 0, "Amount must be > 0");
        require(amountIn <= maxSingleTradeAmount, "Exceeds single trade limit");
        _checkDailyLimit(amountIn);

        IERC20 tokenInERC20 = IERC20(tokenIn);
        require(tokenInERC20.balanceOf(address(this)) >= amountIn, "Insufficient input");

        // 记录输出余额增量
        uint256 balanceBeforeOut = IERC20(tokenOut).balanceOf(address(this));

        // 授权 DEX
        tokenInERC20.forceApprove(dex, 0);
        tokenInERC20.forceApprove(dex, amountIn);

        // ⚠️ 关键修复：path 必须用 address[] 编码，不能用 encodePacked
        address[] memory path = new address[](2);
        path[0] = tokenIn;
        path[1] = tokenOut;

        bytes memory callData = abi.encodeWithSignature(
            "swapExactTokensForTokens(uint256,uint256,address[],address,uint256)",
            amountIn,
            minAmountOut,
            path,
            address(this),
            block.timestamp + 300
        );

        (bool success, ) = dex.call{value: 0}(callData);
        require(success, "Swap failed");

        outputAmount = IERC20(tokenOut).balanceOf(address(this)) - balanceBeforeOut;

        // 重置授权
        tokenInERC20.forceApprove(dex, 0);
        _updateDailyVolume(amountIn);

        uint256 tradeId = trades.length;
        trades.push(TradeRecord({
            id: tradeId, dex: dex, tokenIn: tokenIn, tokenOut: tokenOut,
            inputAmount: amountIn, outputAmount: outputAmount, pnl: 0,
            timestamp: block.timestamp, success: true
        }));
        totalTrades++;
        emit TradeExecuted(tradeId, dex, amountIn, outputAmount, block.timestamp);
    }

    /**
     * @notice 执行 BNB→Token swap
     */
    function swapBNBForTokens(
        address dex,
        address tokenOut,
        uint256 minAmountOut
    ) external payable onlyTrader whenNotPaused returns (uint256 outputAmount) {
        require(approvedDexes[dex], "DEX not approved");
        require(msg.value > 0, "Must send BNB");
        require(msg.value <= maxSingleTradeAmount, "Exceeds single trade limit");
        _checkDailyLimit(msg.value);

        uint256 balanceBefore = IERC20(tokenOut).balanceOf(address(this));

        // ⚠️ 关键修复：path 必须用 address[] 编码
        address[] memory path = new address[](2);
        path[0] = WBNB;
        path[1] = tokenOut;

        bytes memory callData = abi.encodeWithSignature(
            "swapExactETHForTokens(uint256,address[],address,uint256)",
            minAmountOut,
            path,
            address(this),
            block.timestamp + 300
        );

        (bool success, ) = dex.call{value: msg.value}(callData);
        require(success, "BNB swap failed");

        outputAmount = IERC20(tokenOut).balanceOf(address(this)) - balanceBefore;
        _updateDailyVolume(msg.value);

        uint256 tradeId = trades.length;
        trades.push(TradeRecord({
            id: tradeId, dex: dex, tokenIn: WBNB, tokenOut: tokenOut,
            inputAmount: msg.value, outputAmount: outputAmount, pnl: 0,
            timestamp: block.timestamp, success: true
        }));
        totalTrades++;
        emit TradeExecuted(tradeId, dex, msg.value, outputAmount, block.timestamp);
    }

    // ============ 收益结算 ============

    function recordPnl(int256 pnlAmount) external onlyTrader {
        totalPnl += pnlAmount;

        if (pnlAmount > 0) {
            uint256 fee = (uint256(pnlAmount) * platformFeeBps) / 10000;
            if (fee > 0) {
                IERC20 usdt = IERC20(USDT);
                uint256 balance = usdt.balanceOf(address(this));
                if (balance >= fee) {
                    usdt.safeTransfer(platformFeeWallet, fee);
                    totalFeesCollected += fee;
                    emit PlatformFeeCollected(fee, block.timestamp);
                }
            }
        }
    }

    // ============ 权限管理（只有 owner）===========

    function setTrader(address _trader) external onlyOwner {
        require(_trader != address(0), "Invalid trader");
        address old = trader;
        trader = _trader;
        emit TraderUpdated(old, _trader);
    }

    function setTradeLimits(uint256 _maxSingle, uint256 _dailyLimit) external onlyOwner {
        maxSingleTradeAmount = _maxSingle;
        dailyTradeLimit = _dailyLimit;
        emit TradeLimitsUpdated(_maxSingle, _dailyLimit);
    }

    function setDexApproval(address dex, bool approved) external onlyOwner {
        approvedDexes[dex] = approved;
        emit DexApproved(dex, approved);
    }

    function revokeTrader() external onlyOwner {
        address old = trader;
        trader = address(0);
        approvedDexes[PANCAKE_V2_ROUTER] = false;
        approvedDexes[PANCAKE_V3_ROUTER] = false;
        _pause();
        emit TraderUpdated(old, address(0));
        emit EmergencyStop(block.timestamp);
    }

    function emergencyPause() external onlyOwner {
        _pause();
        emit EmergencyStop(block.timestamp);
    }

    function resume() external onlyOwner {
        _unpause();
        approvedDexes[PANCAKE_V2_ROUTER] = true;
        approvedDexes[PANCAKE_V3_ROUTER] = true;
    }

    // ============ 内部函数 ============

    function _checkDailyLimit(uint256 amount) internal {
        if (block.timestamp >= dailyResetTimestamp + 1 days) {
            dailyTradeVolume = 0;
            dailyResetTimestamp = block.timestamp;
        }
        require(dailyTradeVolume + amount <= dailyTradeLimit, "Exceeds daily trade limit");
    }

    function _updateDailyVolume(uint256 amount) internal {
        if (block.timestamp >= dailyResetTimestamp + 1 days) {
            dailyTradeVolume = 0;
            dailyResetTimestamp = block.timestamp;
        }
        dailyTradeVolume += amount;
    }

    // ============ 查询函数 ============

    function getUSDTBalance() external view returns (uint256) {
        return IERC20(USDT).balanceOf(address(this));
    }

    function getBNBBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getTradeCount() external view returns (uint256) {
        return trades.length;
    }

    function getTrader() external view returns (address) {
        return trader;
    }

    function isPaused() external view returns (bool) {
        return paused();
    }

    receive() external payable {}
}

contracts/RevenueDistribution.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AI Quant Agent Revenue Distribution Contract
 * @notice 链上收益分配，自动 70/20/10 分配
 * @dev 部署在 BSC，所有交易透明可验证
 * 
 * 分配规则：
 *   用户收益 70% → 用户钱包
 *   平台提成 20% → 平台钱包
 *   生态基金 10% → 生态基金钱包
 * 
 * 特性：
 *   - Owner（你）可以更新分配比例（有上限约束）
 *   - Owner 可以暂停合约
 *   - 用户可以查询自己的收益记录
 *   - 所有分配事件上链，完全透明
 */

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract RevenueDistribution is Ownable, Pausable, ReentrancyGuard {

    // ============ 状态变量 ============

    address public platformWallet;
    address public ecoFundWallet;

    // 分配比例（基点，1bp = 0.01%）
    uint256 public userShareBps = 7000;    // 70%
    uint256 public platformFeeBps = 2000;  // 20%
    uint256 public ecoFundBps = 1000;      // 10%

    // 平台月费
    uint256 public monthlyFeeUsd = 2990;   // $29.90 (2位小数)

    // 用户记录: userId → { wallet, totalEarned, totalFee, lastDistribution, subscription }
    struct UserRecord {
        address wallet;
        uint256 totalEarned;      // 总收益 (USDT)
        uint256 totalFee;         // 总支付的平台费
        uint256 lastDistribution; // 最后一次分配时间
        uint8  subscription;      // 0=free, 1=basic, 2=pro
        bool   exists;
    }

    mapping(uint256 => UserRecord) public users;  // userId => UserRecord

    // 收益记录: recordIndex => { userId, amount, distribution, timestamp }
    struct RevenueRecord {
        uint256 userId;
        uint256 pnlAmount;
        uint256 userShare;
        uint256 platformFee;
        uint256 ecoFund;
        uint256 timestamp;
    }

    RevenueRecord[] public revenueRecords;

    // 统计
    uint256 public totalDistributed;
    uint256 public totalPlatformFees;
    uint256 public totalEcoFund;
    uint256 public totalTrades;

    // ============ 事件 ============

    event UserRegistered(uint256 indexed userId, address wallet, uint8 subscription);
    event RevenueDistributed(
        uint256 indexed userId,
        uint256 pnlAmount,
        uint256 userShare,
        uint256 platformFee,
        uint256 ecoFund,
        uint256 timestamp
    );
    event WalletUpdated(uint256 indexed userId, address newWallet);
    event SubscriptionUpdated(uint256 indexed userId, uint8 newSubscription);
    event AllocationUpdated(uint256 userBps, uint256 platformBps, uint256 ecoBps);

    // ============ 修饰器 ============

    modifier onlyPlatform() {
        require(msg.sender == platformWallet || msg.sender == owner(), "Not authorized");
        _;
    }

    // ============ 构造函数 ============

    constructor(address _platformWallet, address _ecoFundWallet) Ownable(msg.sender) {
        require(_platformWallet != address(0), "Invalid platform wallet");
        require(_ecoFundWallet != address(0), "Invalid eco fund wallet");
        platformWallet = _platformWallet;
        ecoFundWallet = _ecoFundWallet;
    }

    // ============ 核心函数 ============

    /**
     * @notice 分配收益（由后端 Oracle 调用）
     * @param userId 用户ID
     * @param pnlAmount 盈亏金额（正=盈利，负=亏损）
     */
    function distribute(uint256 userId, int256 pnlAmount) external onlyPlatform whenNotPaused {
        require(pnlAmount > 0, "Only distribute on profit");
        require(users[userId].exists, "User not registered");

        uint256 amount = uint256(pnlAmount);

        // 计算分配
        uint256 userShare = (amount * userShareBps) / 10000;
        uint256 platformFee = (amount * platformFeeBps) / 10000;
        uint256 ecoFund = (amount * ecoFundBps) / 10000;

        // 转账 USDT 到各自钱包
        // 注意：实际部署时需要集成 USDT 合约的 transfer
        // 这里用 BNB 作为示例，生产环境改为 USDT

        UserRecord storage user = users[userId];
        user.totalEarned += userShare;
        user.totalFee += platformFee;
        user.lastDistribution = block.timestamp;

        totalDistributed += userShare;
        totalPlatformFees += platformFee;
        totalEcoFund += ecoFund;
        totalTrades++;

        // 记录
        revenueRecords.push(RevenueRecord({
            userId: userId,
            pnlAmount: amount,
            userShare: userShare,
            platformFee: platformFee,
            ecoFund: ecoFund,
            timestamp: block.timestamp
        }));

        emit RevenueDistributed(userId, amount, userShare, platformFee, ecoFund, block.timestamp);
    }

    /**
     * @notice 注册用户
     */
    function registerUser(uint256 userId, address wallet, uint8 subscription) external onlyPlatform {
        require(!users[userId].exists, "User already registered");
        require(wallet != address(0), "Invalid wallet");

        users[userId] = UserRecord({
            wallet: wallet,
            totalEarned: 0,
            totalFee: 0,
            lastDistribution: 0,
            subscription: subscription,
            exists: true
        });

        emit UserRegistered(userId, wallet, subscription);
    }

    /**
     * @notice 更新用户钱包地址
     */
    function updateWallet(uint256 userId, address newWallet) external {
        require(users[userId].exists, "User not registered");
        // 只有 owner 或用户本人可以修改
        // 简化：只允许 owner（生产环境用签名验证）
        require(msg.sender == owner(), "Only owner");
        require(newWallet != address(0), "Invalid wallet");

        users[userId].wallet = newWallet;
        emit WalletUpdated(userId, newWallet);
    }

    /**
     * @notice 提现用户收益
     */
    function withdrawEarnings(uint256 userId) external nonReentrant {
        UserRecord storage user = users[userId];
        require(user.exists, "User not registered");
        require(user.totalEarned > 0, "No earnings");

        uint256 amount = user.totalEarned;
        user.totalEarned = 0;

        // 转账 USDT 到用户钱包
        // payable(user.wallet).transfer(amount); // BNB
        // 生产环境：IERC20(USDT).transfer(user.wallet, amount);

        emit RevenueDistributed(userId, 0, amount, 0, 0, block.timestamp);
    }

    // ============ 管理函数 ============

    /**
     * @notice 更新分配比例
     * @dev 三个比例之和必须等于 10000 (100%)
     * @dev 单项上限：平台费 ≤ 30%，生态基金 ≤ 20%
     */
    function updateAllocation(uint256 _userBps, uint256 _platformBps, uint256 _ecoBps) external onlyOwner {
        require(_userBps + _platformBps + _ecoBps == 10000, "Must sum to 100%");
        require(_platformBps <= 3000, "Platform fee max 30%");
        require(_ecoBps <= 2000, "Eco fund max 20%");

        userShareBps = _userBps;
        platformFeeBps = _platformBps;
        ecoFundBps = _ecoBps;

        emit AllocationUpdated(_userBps, _platformBps, _ecoBps);
    }

    /**
     * @notice 更新平台钱包
     */
    function updatePlatformWallet(address _newWallet) external onlyOwner {
        require(_newWallet != address(0), "Invalid wallet");
        platformWallet = _newWallet;
    }

    /**
     * @notice 更新生态基金钱包
     */
    function updateEcoFundWallet(address _newWallet) external onlyOwner {
        require(_newWallet != address(0), "Invalid wallet");
        ecoFundWallet = _newWallet;
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    // ============ 查询函数 ============

    function getUserRecord(uint256 userId) external view returns (UserRecord memory) {
        require(users[userId].exists, "User not registered");
        return users[userId];
    }

    function getUserEarnings(uint256 userId) external view returns (uint256) {
        return users[userId].totalEarned;
    }

    function getRevenueRecord(uint256 index) external view returns (RevenueRecord memory) {
        require(index < revenueRecords.length, "Index out of bounds");
        return revenueRecords[index];
    }

    function getRevenueCount() external view returns (uint256) {
        return revenueRecords.length;
    }

    /**
     * @notice 获取分配比例信息
     */
    function getAllocationInfo() external view returns (
        uint256 userPct,
        uint256 platformPct,
        uint256 ecoPct,
        address platformWalletAddr,
        address ecoFundWalletAddr
    ) {
        return (userShareBps / 100, platformFeeBps / 100, ecoFundBps / 100, platformWallet, ecoFundWallet);
    }

    // 接收 BNB
    receive() external payable {}
}

